CREATE TABLE passkey_credential(internal_pk BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id VARCHAR(36) UNIQUE NOT NULL,user_id VARCHAR(36) NOT NULL REFERENCES app_user(id),credential_id VARCHAR(2048) UNIQUE NOT NULL,public_key TEXT NOT NULL,signature_count BIGINT NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE passkey_challenge(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36),purpose VARCHAR(20) NOT NULL,session_hash VARCHAR(64) NOT NULL,request_json TEXT NOT NULL,expires_at VARCHAR(40) NOT NULL,used BOOLEAN NOT NULL);
